import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def connect_via_aligned_pair(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=0]
    pair=None
    for i in range(len(pts)):
        for j in range(i+1,len(pts)):
            a,b=pts[i],pts[j]
            if a[0]==b[0] or a[1]==b[1]: pair=(a,b)
    a,b=pair
    if a[0]==b[0]:
        r=a[0]; lo,hi=sorted((a[1],b[1]))
        for c in range(lo+1,hi): out[r][c]=3
        for (pr,pc) in pts:
            if (pr,pc) in (a,b): continue
            for rr in range(min(pr,r)+1,max(pr,r)): out[rr][pc]=3
    else:
        c=a[1]; lo,hi=sorted((a[0],b[0]))
        for r in range(lo+1,hi): out[r][c]=3
        for (pr,pc) in pts:
            if (pr,pc) in (a,b): continue
            for cc in range(min(pc,c)+1,max(pc,c)): out[pr][cc]=3
    return out

